// Hand-written ad playbooks for US local-service trades (/ad-examples/<trade> and /ad-examples/ideas/...). Pure data.
// Honesty rules (enforced by tests): no statistics, no promised results, no "guaranteed", no real or invented business
// names. Budgets are starting-test guidance only. Builders live in trade-playbooks.ts.

export type TradeCategory = "home-services" | "health-beauty" | "auto" | "professional" | "food-events";
export type SeasonKey = "black-friday" | "spring" | "summer" | "fall" | "winter" | "back-to-school" | "tax-season" | "new-year" | "valentines-day" | "mothers-day" | "holiday-season";
export type Ticket = "low" | "mid" | "high";
export type TradeAction = "call" | "quote" | "book" | "visit" | "order";

export interface Playbook {
  /** Matches an INDUSTRIES slug (src/lib/ads/industries.ts). */
  slug: string;
  category: TradeCategory;
  /** Search term for titles: "roofing" -> "Roofing ad examples". */
  term: string;
  /** Main jobs, plain words (3-4). */
  services: string[];
  /** Opening lines (4), written for the moment the customer is in. */
  hooks: string[];
  /** Offers that are common in the trade (3). */
  offers: string[];
  /** Trust signals to show (3). */
  proof: string[];
  /** Which formats fit, 1-2 sentences. */
  formats: string;
  ticket: Ticket;
  action: TradeAction;
  /** When demand peaks. */
  peak: string;
  /** Trade-specific seasonal ideas (only where they genuinely fit). */
  seasonal: Partial<Record<SeasonKey, string>>;
  /** Ad-policy or honesty note specific to the trade. */
  note?: string;
}

const P = (p: Playbook) => p;

